export type CacheSnapshot = { keys: number; updatedAt: string | null; status: "empty" | "healthy" | "stale" };
export class KnowledgeCache<T> { private values = new Map<string, { value: T; updatedAt: string }>(); set(key: string, value: T, now = new Date().toISOString()) { this.values.set(key, { value, updatedAt: now }); return value; } get(key: string) { return this.values.get(key)?.value ?? null; } snapshot(): CacheSnapshot { const updates = Array.from(this.values.values()).map((v) => v.updatedAt).sort(); return { keys: this.values.size, updatedAt: updates.at(-1) ?? null, status: this.values.size ? "healthy" : "empty" }; } }
